import numpy as np

def rank_vectors(query, records, k):
    if k <= 0:
        return []
    q = np.asarray(query, dtype=float)
    q_norm = np.linalg.norm(q)
    results = []
    for record in records:
        vector = np.asarray(record["vector"], dtype=float)
        denominator = q_norm * np.linalg.norm(vector)
        score = float(np.dot(q, vector) / denominator) if denominator else 0.0
        results.append({"id": record["id"], "score": score})
    return sorted(results, key=lambda row: (-row["score"], row["id"]))[:k]

def search(query, documents, k=3, team=None, min_score=0.0):
    candidates = [d for d in documents if team is None or d.get("team") == team]
    lookup = {d["id"]: d for d in candidates}
    return [{"id": hit["id"], "text": lookup[hit["id"]]["text"], "score": hit["score"]}
            for hit in rank_vectors(query, candidates, k)
            if hit["score"] >= min_score]

def pack_context(chunks, budget):
    lines, ids = [], []
    if budget <= 0:
        return {"context": "", "ids": []}
    used = 0
    for chunk in chunks:
        line = f"[{chunk['id']}] {chunk['text']}"
        cost = len(line) + (1 if lines else 0)
        if used + cost <= budget:
            lines.append(line)
            ids.append(chunk["id"])
            used += cost
    return {"context": "\n".join(lines), "ids": ids}

