import numpy as np

def train_centroids(X, labels):
    matrix = np.asarray(X, dtype=float)
    if matrix.ndim != 2 or matrix.shape[0] == 0 or matrix.shape[0] != len(labels):
        raise ValueError("expected a nonempty matrix and one label per row")
    labels_array = np.asarray(labels)
    return {label: matrix[labels_array == label].mean(axis=0) for label in sorted(set(labels))}

def evaluate_classifier(train_texts, train_labels, test_texts, test_labels, vocabulary):
    if len(test_texts) != len(test_labels):
        raise ValueError("one test label is required per text")
    model = train_centroids(vectorize(train_texts, vocabulary), train_labels)
    predictions = []
    for row in vectorize(test_texts, vocabulary):
        _, label = min((float(np.sum((row-center)**2)), label) for label, center in model.items())
        predictions.append(label)
    accuracy = sum(a == b for a, b in zip(predictions, test_labels)) / len(test_labels) if test_labels else None
    return {"predictions": predictions, "accuracy": accuracy}

