import math

def validate_invoice(value):
    if not isinstance(value, dict) or set(value) != {"vendor", "amount"}:
        raise ValueError("expected vendor and amount only")
    vendor, amount = value["vendor"], value["amount"]
    if not isinstance(vendor, str) or not vendor.strip():
        raise ValueError("vendor must be nonempty")
    if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0:
        raise ValueError("amount must be finite and nonnegative")
    try:
        finite = math.isfinite(amount)
    except OverflowError:
        finite = False
    if not finite:
        raise ValueError("amount must be finite and nonnegative")
    return {"vendor": vendor.strip(), "amount": float(amount)}

