def research(question, documents, max_steps=3):
    notes, trace = [], []
    result = {"status": "budget_exhausted", "notes": notes, "trace": trace, "simulated": True}
    if max_steps <= 0:
        return result
    call = {"tool": "search", "args": {"query": question}}
    observation = execute_tool(call, documents)
    trace.append({"call": call, "observation": observation})
    if not observation["ids"]:
        result["status"] = "no_evidence"
        return result
    for source_id in observation["ids"][:2]:
        if len(trace) >= max_steps:
            return result
        call = {"tool": "fetch", "args": {"id": source_id}}
        fetched = execute_tool(call, documents)
        trace.append({"call": call, "observation": fetched})
        notes.append(fetched)
    result["status"] = "complete"
    return result

