def evidence_workflow(topics, sources):
    candidates, missing = [], []
    for topic in topics:
        match = next(((source_id, text) for source_id, text in sources.items() if topic.lower() in text.lower()), None)
        if match is None:
            missing.append(topic)
        else:
            source_id, text = match
            candidates.append({"text": text, "source_id": source_id, "quote": text})
    reviewed = review_claims(candidates, sources)
    lines = [f"{claim['text']} [{claim['source_id']}]" for claim in reviewed["accepted"]]
    return {"report": "\n".join(lines) if lines else "Insufficient evidence.",
            "missing": missing,
            "audit": {"proposed": len(candidates), "accepted": len(reviewed["accepted"]), "rejected": len(reviewed["rejected"])},
            "simulated": True}

