    return any(normalized == " ".join(reference.lower().split()) for reference in references)

def citation_metrics(citations, allowed_ids):
    unique = list(dict.fromkeys(citations))
    allowed = set(allowed_ids)
    invalid = [source_id for source_id in unique if source_id not in allowed]
    precision = (len(unique) - len(invalid)) / len(unique) if unique else None
    return {"precision": precision, "invalid": invalid, "count": len(unique)}

def evaluate_suite(cases, outputs):
    results = []
    for case in cases:
        output = outputs.get(case["id"], {"answer": "", "citations": []})
        correct = exact_match(output["answer"], case["references"])
        metrics = citation_metrics(output["citations"], case["allowed_ids"])
        passed = correct and not metrics["invalid"] and (not case["require_citation"] or metrics["count"] > 0)
        results.append({"id": case["id"], "answer_correct": correct,
                        "citation_precision": metrics["precision"], "invalid_citations": metrics["invalid"], "passed": passed})
    return {"results": results, "pass_rate": sum(row["passed"] for row in results) / len(results) if results else None}

def validate_request(payload):
    if not isinstance(payload, dict) or "query" not in payload or not set(payload) <= {"query", "limit"}:
        raise ValueError("expected query and optional limit")
    if not isinstance(payload["query"], str):
        raise ValueError("query must be text")
    query = " ".join(payload["query"].split())
    limit = payload.get("limit", 3)
    if not 1 <= len(query) <= 200:
        raise ValueError("query length must be 1..200")
    if type(limit) is not int or not 1 <= limit <= 10:
        raise ValueError("limit must be an integer from 1 to 10")
    return {"query": query, "limit": limit}

