from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, ConfigDict, Field, StrictInt, field_validator
import re

app = FastAPI(title="PyQuest search API", description="Deterministic lexical retrieval simulator")
DOCUMENTS = [{"id": "guide", "text": "Cache policy stores repeated query results."},
             {"id": "limits", "text": "Rate limits protect a service from overload."}]
CACHE = {}

class SearchRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    query: str
    limit: StrictInt = Field(default=3, ge=1, le=10)

    @field_validator("query")
    @classmethod
    def normalize_query(cls, value):
        value = " ".join(value.split())
        if not 1 <= len(value) <= 200:
            raise ValueError("query length must be 1..200")
        return value

@app.post("/search")
def search(request: SearchRequest):
    key = (request.query.lower(), request.limit)
    cache_hit = key in CACHE
    if not cache_hit:
        terms = set(re.findall(r"[a-z]+", key[0]))
        hits = []
        for document in DOCUMENTS:
            score = len(terms & set(re.findall(r"[a-z]+", document["text"].lower())))
            if score:
                hits.append({**document, "score": score})
        CACHE[key] = sorted(hits, key=lambda hit: (-hit["score"], hit["id"]))[:request.limit]
    return {"hits": [dict(hit) for hit in CACHE[key]], "cache_hit": cache_hit, "simulated": True}

@app.get("/health")
def health():
    return {"status": "ok"}

